#!/usr/bin/env python3
"""Derive db.py verbs -> writer functions -> tables written, refusals. usage: probe_verbs.py REPO OUT.json"""
import ast, json, re, sys
from pathlib import Path
repo = Path(sys.argv[1]); src = (repo / "scripts/db.py").read_text(encoding="utf-8")
tree = ast.parse(src)
funcs = {n.name: n for n in tree.body if isinstance(n, ast.FunctionDef)}
SQLW = re.compile(r'\b(INSERT\s+(?:OR\s+\w+\s+)?INTO|UPDATE|DELETE\s+FROM)\s+"?(\w+)"?', re.I)
def strings(node):
    for n in ast.walk(node):
        if isinstance(n, ast.Constant) and isinstance(n.value, str): yield n.value
        elif isinstance(n, ast.JoinedStr):
            yield "".join(v.value if isinstance(v, ast.Constant) else "{}" for v in n.values)
def writes(fn, seen=None, depth=0):
    seen = seen or set(); out = {}
    if fn.name in seen or depth > 3: return out
    seen.add(fn.name)
    for s in strings(fn):
        for m in SQLW.finditer(s):
            op = m.group(1).split()[0].upper(); t = m.group(2)
            if t.lower() in ("set", "values", "select", "or"): continue
            out.setdefault(t, set()).add(op)
    for n in ast.walk(fn):
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id in funcs and n.func.id != fn.name:
            for t, ops in writes(funcs[n.func.id], seen, depth + 1).items(): out.setdefault(t, set()).update(ops)
    return out
def refusals(fn):
    k = 0
    for n in ast.walk(fn):
        if isinstance(n, ast.Raise) and isinstance(n.exc, ast.Call) and getattr(n.exc.func, "id", getattr(n.exc.func, "attr", "")) == "Refusal": k += 1
    return k
def called_funcs(stmts):
    names = []
    for st in stmts:
        for n in ast.walk(st):
            if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id in funcs: names.append(n.func.id)
            elif isinstance(n, ast.Call) and isinstance(n.func, ast.Attribute) and isinstance(n.func.value, ast.Name) and n.func.value.id == "db": pass
    return list(dict.fromkeys(names))
main = funcs["main"]
verbs = {}
def walk_if(node):
    # args.command == "x"  (also `in (...)`)
    for n in ast.walk(node):
        if isinstance(n, ast.If):
            t = n.test
            if isinstance(t, ast.Compare) and isinstance(t.left, ast.Attribute) and t.left.attr == "command":
                cmp = t.comparators[0]
                names = [cmp.value] if isinstance(cmp, ast.Constant) else [e.value for e in getattr(cmp, "elts", []) if isinstance(e, ast.Constant)]
                for v in names:
                    if v in verbs: continue
                    fs = called_funcs(n.body)
                    verbs[v] = fs
walk_if(main)
declared = re.findall(r'add_parser\(\s*"([^"]+)"', src)
res = {"declared_verbs": declared, "verbs": {}}
for v in declared:
    fs = verbs.get(v, [])
    w = {}; ref = 0
    for f in fs:
        for t, ops in writes(funcs[f]).items(): w.setdefault(t, set()).update(ops)
        ref += refusals(funcs[f])
    res["verbs"][v] = {"functions": fs, "writes": {t: sorted(o) for t, o in sorted(w.items())}, "refusal_sites": ref}
res["undispatched"] = [v for v in declared if v not in verbs]
json.dump(res, open(sys.argv[2], "w"), indent=1)
w_tables = sorted({t for v in res["verbs"].values() for t in v["writes"]})
print("verbs declared", len(declared), "| undispatched by analysis:", res["undispatched"])
print("tables written by some verb:", len(w_tables))
