REPO = Path('/home/user/guidebook')
atoms = []
_cache = {}
SM = {'b':'base','r':'research','e':'evidence','j':'judgment','s':'synthesis','p':'specification','n':'render','x':'cross'}

def lines_of(path):
    if path not in _cache:
        _cache[path] = (REPO/path).read_text(encoding='utf-8').split('\n')
    return _cache[path]
def norm(s): return re.sub(r'\s+',' ',s).strip()
def strip(l): return re.sub(r'^\s*>\s?','',l)
def find_line(path, quote, ln=1):
    ls = lines_of(path)
    nq = norm(re.sub(r'^\s*>\s?','',quote))
    head = nq[:25]
    for i in range(max(ln-1,0), len(ls)):
        for w in range(1,5):
            win = norm(" ".join(strip(l) for l in ls[i:i+w]))
            if nq in win and head in norm(strip(ls[i])):
                return i+1
    return None

def mk(path, spk_default):
    def f(quote, mod, subj, claim, st_, objs=(), spk=None, date=None, status='ACTIVE', se=None, sb=None, enf=None, amb=None, ln=1):
        assert len(quote) <= 300, (len(quote), quote[:60])
        line = find_line(path, quote, ln)
        if line is None:
            print("QUOTE NOT FOUND:", path, quote[:80]); return
        if status != 'ACTIVE' and se is None:
            print("MISSING status_evidence:", quote[:60])
        atoms.append({
            "id": None, "source": f"{path}:{line}", "quote": quote, "modality": mod, "subject": subj, "claim": claim,
            "scope": {"stages": [SM[c] for c in st_], "objects": list(objs)},
