"""Candidate conflict pairs among ACTIVE atoms. A candidate is a place to look, not a finding."""
import json, re, itertools, collections, sys
A = [json.loads(l) for l in open("flat.jsonl", encoding="utf-8")]
act = [a for a in A if a["status"] in ("ACTIVE", "AMENDED", "OPEN", "PROPOSED")]
STOP = set("the a an of to in and or for is are be by on with as that this it its at from not no never must may should shall any all each every one two into than then when where which who whose".split())
tok = lambda s: {w for w in re.findall(r"[a-z0-9_\-]{3,}", (s or "").lower()) if w not in STOP}
obj = lambda a: {o.lower().strip("`") for o in a["objects"] if len(o) > 2}
for a in act:
    a["_st"] = tok(a["subject"]); a["_ct"] = tok(a["claim"]); a["_ob"] = obj(a)
OPP = {("MUST", "MUST_NOT"), ("MUST_NOT", "MUST"), ("MAY", "MUST_NOT"), ("MUST_NOT", "MAY")}
cand = []
idx = collections.defaultdict(list)
for i, a in enumerate(act):
    for o in a["_ob"]: idx[o].append(i)
seen = set()
for o, lst in idx.items():
    if len(lst) > 40: continue          # ubiquitous object (e.g. 'db.py'): no signal
    for i, j in itertools.combinations(lst, 2):
        if (i, j) in seen: continue
        seen.add((i, j)); a, b = act[i], act[j]
        if a["source"].split(":")[0] == b["source"].split(":")[0]: same = True
        else: same = False
        stagesh = set(a["stages"]) & set(b["stages"])
        if not stagesh: continue
        jac = len(a["_ct"] & b["_ct"]) / max(1, len(a["_ct"] | b["_ct"]))
        sig = []
        if (a["modality"], b["modality"]) in OPP and jac >= 0.12: sig.append("OPPOSING-MODALITY")
        if a["modality"] == b["modality"] == "CARDINALITY" and a["claim"] != b["claim"]: sig.append("CARDINALITY-DIFF")
        if a["modality"] in ("DEFINES", "EQUATES") and b["modality"] in ("DEFINES", "EQUATES") and a["_st"] & b["_st"] and jac < 0.5: sig.append("DEFINITION-DIFF")
        if a["modality"] == b["modality"] == "ORDER" and a["claim"] != b["claim"]: sig.append("ORDER-DIFF")
        if sig: cand.append((len(a["_ob"] & b["_ob"]), sig, a["id"], b["id"], sorted(a["_ob"] & b["_ob"])[:4], same))
cand.sort(key=lambda c: (-len(c[1]), -c[0]))
print("active atoms:", len(act), "| candidate pairs:", len(cand), "| cross-document:", sum(1 for c in cand if not c[5]))
json.dump([dict(shared=c[0], signals=c[1], a=c[2], b=c[3], objects=c[4], same_doc=c[5]) for c in cand], open("pairs.json", "w"), indent=0)
