"""Row-level diff of every table between two SQLite DBs, keyed on the PK (or rowid).
usage: rowdiff.py A B [table ...]   (A = left/"old", B = right/"new")"""
import sqlite3, sys, json
a, b = sys.argv[1], sys.argv[2]
only = set(sys.argv[3:])
ca = sqlite3.connect(f'file:{a}?mode=ro', uri=True)
cb = sqlite3.connect(f'file:{b}?mode=ro', uri=True)
def tables(c): return {n for (n,) in c.execute("select name from sqlite_master where type='table' and name not like 'sqlite_%'")}
ta, tb = tables(ca), tables(cb)
for t in sorted(ta ^ tb):
    if only and t not in only: continue
    print(f"TABLE-ONLY-IN-{'A' if t in ta else 'B'}: {t}")
for t in sorted(ta & tb):
    if only and t not in only: continue
    info = list(ca.execute(f'PRAGMA table_info("{t}")'))
    cols = [r[1] for r in info]
    colsb = [r[1] for r in cb.execute(f'PRAGMA table_info("{t}")')]
    if cols != colsb:
        print(f"SCHEMA-DIFF {t}: {set(cols)^set(colsb)}"); continue
    pk = [r[1] for r in sorted(info, key=lambda r: r[5]) if r[5]]
    if not pk:
        # use full-row multiset compare
        ra = sorted(map(repr, ca.execute(f'select * from "{t}"')))
        rb = sorted(map(repr, cb.execute(f'select * from "{t}"')))
        if ra != rb:
            sa, sb = set(ra), set(rb)
            print(f"== {t} (no PK; multiset) only-in-A={len([x for x in ra if x not in sb])} only-in-B={len([x for x in rb if x not in sa])}")
            for x in ra:
                if x not in sb: print("   A-only", x)
            for x in rb:
                if x not in sa: print("   B-only", x)
        continue
    sel = ", ".join(f'"{c}"' for c in cols)
    da = {tuple(r[cols.index(k)] for k in pk): r for r in ca.execute(f'select {sel} from "{t}"')}
    db = {tuple(r[cols.index(k)] for k in pk): r for r in cb.execute(f'select {sel} from "{t}"')}
    out = []
    for k in sorted(set(da) | set(db), key=repr):
        if k not in da: out.append(f"   B-only {dict(zip(cols, db[k]))}")
        elif k not in db: out.append(f"   A-only {dict(zip(cols, da[k]))}")
        elif da[k] != db[k]:
            for i, c in enumerate(cols):
                if da[k][i] != db[k][i]:
                    out.append(f"   {pk}={list(k)} {c}: A={da[k][i]!r} -> B={db[k][i]!r}")
    if out:
        print(f"== {t} (pk {pk})")
        print("\n".join(out))
