def imports(path):
    try: tree = ast.parse(open(path).read())
    except Exception as e:
        print('PARSE FAIL', path, e, file=sys.stderr); return set()
    out = set()
    for n in ast.walk(tree):
        if isinstance(n, ast.ImportFrom) and n.module:
            if n.module == 'schemas':
                out |= {a.name for a in n.names}
            elif n.module.startswith('schemas.'):
                out.add(n.module.split('.')[1])
        elif isinstance(n, ast.Import):
            for a in n.names:
                if a.name.startswith('schemas.'): out.add(a.name.split('.')[1])
                elif a.name == 'schemas': out.add('__init__')
    return out
inside = {}
for f in files:
    if f.startswith(excl_prefix) or f in skip: continue
    im = imports(f)
    if f.startswith('schemas/'):
        inside[pathlib.Path(f).stem] = im & mods
    else:
        for m in im:
            direct[m].add(f)
roots = set(direct) & mods
keep = set(roots); stack = list(roots)
while stack:
    m = stack.pop()
    for d in inside.get(m, ()):
        if d not in keep: keep.add(d); stack.append(d)
