for m in sorted(roots): print(' ', m, '<-', sorted(direct[m]))
print('KEEP (closure):', sorted(keep))
print('DELETE:', sorted(mods - keep))
for m in sorted(keep - roots): print('  transitive:', m, 'imported by', sorted(k for k,v in inside.items() if m in v and k in keep))
