"""Re-anchor atoms' `source: path:LINE` after an edit shifted lines. Run from the repo root.
Text-level: rewrites only the `"source": "path:N"` token in each jsonl line. Reports atoms whose quote vanished.
Usage: reanchor_atoms.py [--dry]"""
import glob, json, re, sys, importlib.util
from pathlib import Path
repo = Path.cwd()
spec = importlib.util.spec_from_file_location('bg', repo/'workplan/pipeline-state-graph/build_graph.py')
bg = importlib.util.module_from_spec(spec); spec.loader.exec_module(bg)
norm = bg.norm
dry = '--dry' in sys.argv
cache = {}
def lines_of(path):
    if path not in cache:
        cache[path] = (repo/path).read_text(encoding='utf-8', errors='replace').split('\n')
    return cache[path]
def near_ok(path, ln, quote):
    lines = lines_of(path)
    window = norm("\n".join(re.sub(r"^\s*>\s?", "", x) for x in lines[max(0, ln-4): ln+3]))
    head = norm(re.sub(r"^\s*>\s?", "", quote))[:50]
    return head in window
changed, vanished = 0, []
for f in sorted(glob.glob(str(repo/'workplan/pipeline-state-graph/atoms/atoms-*.jsonl'))):
    out = []
    for raw in open(f, encoding='utf-8').read().split('\n'):
        if not raw.strip(): out.append(raw); continue
        a = json.loads(raw)
        m = re.match(r'^(.*):(\d+)$', a['source'])
        if m:
            path, ln = m.group(1), int(m.group(2))
            try: n = len(lines_of(path))
            except FileNotFoundError: vanished.append((a['id'], 'file gone ' + path)); out.append(raw); continue
            if not near_ok(path, ln, a['quote']):
                found = None
                for d in range(1, n):
                    for cand in (ln - d, ln + d):
                        if 1 <= cand <= n and near_ok(path, cand, a['quote']):
                            found = cand; break
                    if found: break
                if found:
                    raw = raw.replace(f'"source": "{a["source"]}"', f'"source": "{path}:{found}"', 1)
                    changed += 1
                else:
                    vanished.append((a['id'], f'quote gone from {path}'))
        out.append(raw)
    if not dry: open(f, 'w', encoding='utf-8').write('\n'.join(out))
print('reanchored', changed, 'vanished', vanished)
