"""Text-level source edits (no reformatting). Import from other scripts."""
import ast, re

def load(p): return open(p, encoding='utf-8').read()
def save(p, t): open(p, 'w', encoding='utf-8').write(t)

def remove_def(src, name, also_comment_above=False):
    """Remove a top-level (or any-level) function/class named `name`; returns new src. Includes decorators."""
    tree = ast.parse(src)
    lines = src.split('\n')
    hit = None
    for n in ast.walk(tree):
        if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)) and n.name == name:
            hit = n; break
    if hit is None: raise KeyError(name)
    start = (min([d.lineno for d in hit.decorator_list]) if hit.decorator_list else hit.lineno) - 1
    end = hit.end_lineno
    if also_comment_above:
        while start > 0 and lines[start-1].startswith('#'): start -= 1
    # swallow following blank lines but leave two before the next top-level item
    while end < len(lines) and lines[end].strip() == '': end += 1
    indent_top = hit.col_offset == 0
    keep_blank = 2 if indent_top else 1
    new = lines[:start] + ([''] * keep_blank if end < len(lines) else []) + lines[end:]
    return '\n'.join(new)

def remove_between(src, start_marker, end_marker, keep_end=True, count=1):
    """Remove lines from the line containing start_marker up to (not including) the line containing end_marker (searched after start)."""
    lines = src.split('\n')
    s = next((i for i, l in enumerate(lines) if start_marker in l), None)
    if s is None: raise KeyError(start_marker)
    e = next((i for i in range(s + 1, len(lines)) if end_marker in lines[i]), None)
    if e is None: raise KeyError(end_marker)
    return '\n'.join(lines[:s] + lines[e:])

def remove_branch(src, header):
    """Remove an if/elif branch whose header line (stripped) == header, through the line before the next sibling branch (same indent: elif/else/if) ."""
    lines = src.split('\n')
    s = next((i for i, l in enumerate(lines) if l.strip() == header), None)
    if s is None: raise KeyError(header)
    ind = len(lines[s]) - len(lines[s].lstrip())
    e = s + 1
    while e < len(lines):
        l = lines[e]
        if l.strip() and (len(l) - len(l.lstrip())) <= ind: break
        e += 1
    return '\n'.join(lines[:s] + lines[e:])

def sub1(src, old, new):
    assert src.count(old) == 1, (src.count(old), old[:70])
    return src.replace(old, new)
